import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    n = 32
    # Start from a good structured configuration: place circles on a 6x6 grid
    # and give all a modest radius, then optimise radii/positions greedily.
    if start is not None:
        best = np.array(start, dtype=float)
        # Ensure it's valid-ish; otherwise fall back
        if best.shape != (n, 3):
            best = None
    else:
        best = None

    if best is None:
        k = 6
        pts = []
        for j in range(k):
            for i in range(k):
                pts.append(((i + 0.5) / k, (j + 0.5) / k))
        pts = pts[:n]
        best = np.zeros((n, 3))
        for i, (x, y) in enumerate(pts):
            best[i, 0] = x
            best[i, 1] = y
            best[i, 2] = 0.02

    def total_r(a):
        return a[:, 2].sum()

    def fix(a):
        """Clamp positions so circles fit in square given radii, then shrink on overlaps."""
        a = a.copy()
        # Clamp centers into feasible box for given radius
        for i in range(n):
            r = a[i, 2]
            if r < 0:
                r = 0.0
            if r > 0.5:
                r = 0.5
            a[i, 2] = r
            a[i, 0] = min(max(a[i, 0], r), 1.0 - r)
            a[i, 1] = min(max(a[i, 1], r), 1.0 - r)
        # Resolve overlaps by shrinking radii
        for _ in range(50):
            changed = False
            for i in range(n):
                for j in range(i + 1, n):
                    dx = a[i, 0] - a[j, 0]
                    dy = a[i, 1] - a[j, 1]
                    d = (dx * dx + dy * dy) ** 0.5
                    s = a[i, 2] + a[j, 2]
                    if s > d and s > 1e-15:
                        # shrink both proportionally
                        excess = s - d
                        # reduce each by half excess, but not below tiny
                        a[i, 2] = max(a[i, 2] - excess * 0.5, 1e-9)
                        a[j, 2] = max(a[j, 2] - excess * 0.5, 1e-9)
                        changed = True
            if not changed:
                break
        return a

    best = fix(best)
    best_score = total_r(best)

    rng = np.random.default_rng(12345)

    # Coordinate-descent style: for each circle, try to increase its radius
    # while moving slightly, then repair. Also try perturbing positions.
    def try_improve(a):
        nonlocal best, best_score
        cand = fix(a)
        sc = total_r(cand)
        if sc > best_score:
            best = cand
            best_score = sc
            return True
        return False

    step = 0.05
    while time.process_time() < deadline:
        improved = False
        # attempt to grow each radius
        for i in range(n):
            if time.process_time() >= deadline:
                break
            for dr in (0.01, 0.005, 0.002):
                a = best.copy()
                a[i, 2] += dr
                if try_improve(a):
                    improved = True
                    break
        if not improved:
            # random perturbation of positions
            a = best.copy()
            i = rng.integers(n)
            a[i, 0] += rng.normal(0, step)
            a[i, 1] += rng.normal(0, step)
            if try_improve(a):
                improved = True
            else:
                step *= 0.95
                if step < 1e-4:
                    step = 0.05

    # Final safety: shrink all radii slightly to guarantee zero-tolerance validity
    out = best.copy()
    out[:, 2] *= (1.0 - 1e-9)
    # Re-verify and shrink more if needed
    for _ in range(30):
        ok = True
        for i in range(n):
            r = out[i, 2]
            if r <= 0:
                ok = False
            if out[i, 0] - r < 0 or out[i, 0] + r > 1 or out[i, 1] - r < 0 or out[i, 1] + r > 1:
                ok = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = out[i, 0] - out[j, 0]
                dy = out[i, 1] - out[j, 1]
                d = (dx * dx + dy * dy) ** 0.5
                if d < out[i, 2] + out[j, 2]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            break
        out[:, 2] *= 0.999
        for i in range(n):
            r = out[i, 2]
            out[i, 0] = min(max(out[i, 0], r), 1.0 - r)
            out[i, 1] = min(max(out[i, 1], r), 1.0 - r)

    return out

import numpy as np
import time


def _score(pts):
    return pts[:, 2].sum()


def _valid(pts):
    x = pts[:, 0]; y = pts[:, 1]; r = pts[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -1e-12) or np.any(x + r > 1 + 1e-12):
        return False
    if np.any(y - r < -1e-12) or np.any(y + r > 1 + 1e-12):
        return False
    n = len(pts)
    for i in range(n):
        dx = x[i] - x[i+1:]
        dy = y[i] - y[i+1:]
        d = np.sqrt(dx*dx + dy*dy)
        need = r[i] + r[i+1:]
        if np.any(d < need - 1e-12):
            return False
    return True


def _maximize_radii(pts, iters=2000):
    """Given centres, compute maximal radii greedily then push."""
    n = len(pts)
    x = pts[:, 0].copy(); y = pts[:, 1].copy()
    r = pts[:, 2].copy()
    # simple iterative growth with constraint projection
    for _ in range(iters):
        changed = False
        for i in range(n):
            # wall limits
            lim = min(x[i], 1 - x[i], y[i], 1 - y[i])
            for j in range(n):
                if i == j:
                    continue
                d = np.hypot(x[i]-x[j], y[i]-y[j])
                lim = min(lim, d - r[j])
            if lim > r[i]:
                r[i] = lim
                changed = True
        if not changed:
            break
    return np.column_stack([x, y, r])


def _lapack_solve(pts):
    """Use scipy SLSQP to maximize sum of radii with centres fixed."""
    from scipy.optimize import minimize
    n = len(pts)
    x = pts[:, 0]; y = pts[:, 1]

    def neg_sum(r):
        return -r.sum()

    def grad(r):
        return -np.ones(n)

    cons = []
    # walls
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': lambda r, i=i: r[i] - (x[i])})
        cons.append({'type': 'ineq', 'fun': lambda r, i=i: (1 - x[i]) - r[i]})
        cons.append({'type': 'ineq', 'fun': lambda r, i=i: r[i] - (y[i])})
        cons.append({'type': 'ineq', 'fun': lambda r, i=i: (1 - y[i]) - r[i]})
    # pairs
    for i in range(n):
        for j in range(i+1, n):
            d = np.hypot(x[i]-x[j], y[i]-y[j])
            cons.append({'type': 'ineq',
                         'fun': lambda r, i=i, j=j, d=d: d - r[i] - r[j]})

    r0 = pts[:, 2].copy()
    # feasible start: shrink
    r0 = np.minimum(r0, np.minimum(x, 1-x))
    r0 = np.minimum(r0, np.minimum(y, 1-y))
    for i in range(n):
        for j in range(i+1, n):
            d = np.hypot(x[i]-x[j], y[i]-y[j])
            s = r0[i] + r0[j]
            if s > d:
                f = d / s
                r0[i] *= f; r0[j] *= f
    try:
        res = minimize(neg_sum, r0, jac=grad, constraints=cons,
                       method='SLSQP', options={'maxiter': 500, 'ftol': 1e-12})
        r = res.x
        r = np.maximum(r, 1e-9)
    except Exception:
        r = r0
    return np.column_stack([x, y, r])


def _relax_positions(pts, rounds=3000):
    n = len(pts)
    x = pts[:, 0].copy(); y = pts[:, 1].copy(); r = pts[:, 2].copy()
    for _ in range(rounds):
        moved = False
        for i in range(n):
            # wall forces
            for axis in (0, 1):
                if axis == 0:
                    gap = x[i] - r[i]
                    if gap < 0:
                        x[i] -= gap; moved = True
                    gap = (1 - x[i]) - r[i]
                    if gap < 0:
                        x[i] += gap; moved = True
                else:
                    gap = y[i] - r[i]
                    if gap < 0:
                        y[i] -= gap; moved = True
                    gap = (1 - y[i]) - r[i]
                    if gap < 0:
                        y[i] += gap; moved = True
            for j in range(n):
                if i == j:
                    continue
                dx = x[i] - x[j]; dy = y[i] - y[j]
                d = np.hypot(dx, dy)
                need = r[i] + r[j]
                if d < need and d > 1e-15:
                    push = (need - d) * 0.5
                    ux = dx / d; uy = dy / d
                    x[i] += ux * push; y[i] += uy * push
                    moved = True
        if not moved:
            break
    return np.column_stack([x, y, r])


def _hex_start(n=32):
    pts = []
    k = int(np.ceil(np.sqrt(n)))
    for j in range(k):
        for i in range(k):
            if len(pts) >= n:
                break
            x = (i + 0.5 + (0.5 if j % 2 else 0)) / (k + 0.5)
            y = (j + 0.5) / (k + 0.5)
            x = min(max(x, 0.05), 0.95)
            y = min(max(y, 0.05), 0.95)
            pts.append((x, y, 0.02))
        if len(pts) >= n:
            break
    return np.array(pts[:n])


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
    else:
        best = _hex_start(n)

    # Ensure feasibility
    best = _maximize_radii(best, iters=500)
    best = _relax_positions(best, rounds=2000)
    best = _maximize_radii(best, iters=2000)
    best = _lapack_solve(best)

    best_score = _score(best)

    # Local search: perturb centres and re-optimise radii
    rng = np.random.default_rng(12345)
    attempts = 0
    while True:
        elapsed = time.process_time() - t0
        if elapsed > budget_seconds * 0.85:
            break
        attempts += 1
        cand = best.copy()
        # random perturb of a few centres
        m = rng.integers(1, 4)
        idx = rng.choice(n, size=m, replace=False)
        scale = 0.02 * (1.0 - min(1.0, elapsed / budget_seconds))
        cand[idx, 0] += rng.normal(0, scale, size=m)
        cand[idx, 1] += rng.normal(0, scale, size=m)
        cand[:, 0] = np.clip(cand[:, 0], 1e-4, 1 - 1e-4)
        cand[:, 1] = np.clip(cand[:, 1], 1e-4, 1 - 1e-4)
        # shrink radii to allow movement
        cand[:, 2] *= 0.9
        cand = _relax_positions(cand, rounds=800)
        cand = _maximize_radii(cand, iters=1500)
        cand = _lapack_solve(cand)
        s = _score(cand)
        if s > best_score:
            best = cand
            best_score = s

    # Final safety: shrink slightly to guarantee feasibility
    best = _maximize_radii(best, iters=3000)
    best[:, 2] *= (1 - 1e-9)
    # Verify, shrink more if needed
    for _ in range(20):
        if _valid(best):
            break
        best[:, 2] *= (1 - 1e-7)

    return best
